       "tr": "rahn-plee-SAY too lay for-mew-LEHR · রঁপ্লিসে তু লে ফর্ম্যুলের্",
       "mean": "Fill out all the forms · সব ফরম পূরণ করুন",
       "note": "**fill out** — complete in full · সম্পূর্ণ পূরণ করা"
